  "inlineSchema": '// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = "prisma-client"\n  output   = "../src/generated/prisma"\n}\n\ndatasource db {\n  provider = "postgresql"\n}\n\nmodel Cliente {\n  id           Int      @id @default(autoincrement())\n  nome         String\n  telefone     String   @unique\n  email        String?  @unique\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n}\n\nenum PapelUsuario {\n  CLIENTE\n  FUNCIONARIO\n  DONO\n}\n\nenum StatusAgendamento {\n  SOLICITADO\n  CONFIRMADO\n  RECUSADO\n  CANCELADO_CLIENTE\n  CANCELADO_FUNCIONARIO\n  CONCLUIDO\n  FALTOU\n}\n\nmodel Usuario {\n  id        String       @id @default(cuid())\n  nome      String\n  email     String       @unique\n  telefone  String?      @unique\n  senhaHash String\n  papel     PapelUsuario @default(CLIENTE)\n\n  ativo        Boolean  @default(true)\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  sessoes      Sessao[]\n  profissional Profissional?\n  assinaturas  AssinaturaCliente[] @relation("AssinaturasCliente")\n  agendamentos Agendamento[]       @relation("AgendamentosCliente")\n}\n\nmodel Servico {\n  id             String        @id @default(cuid())\n  nome           String        @unique\n  descricao      String?\n  duracaoMinutos Int\n  precoCentavos  Int\n  ativo          Boolean       @default(true)\n  criadoEm       DateTime      @default(now())\n  atualizadoEm   DateTime      @updatedAt\n  agendamentos   Agendamento[]\n\n  @@index([ativo])\n}\n\nmodel Profissional {\n  id           String   @id @default(cuid())\n  usuarioId    String?  @unique\n  nome         String\n  telefone     String?\n  descricao    String?\n  ativo        Boolean  @default(true)\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  usuario      Usuario?         @relation(fields: [usuarioId], references: [id], onDelete: SetNull)\n  agendamentos Agendamento[]\n  bloqueios    BloqueioAgenda[]\n\n  @@index([ativo])\n}\n\nmodel Sessao {\n  id        String   @id @default(cuid())\n  tokenHash String   @unique\n  usuarioId String\n  expiraEm  DateTime\n  criadoEm  DateTime @default(now())\n\n  usuario Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n\n  @@index([usuarioId])\n  @@index([expiraEm])\n}\n\nenum FormaPagamento {\n  PIX\n  DINHEIRO\n  CARTAO_DEBITO\n  CARTAO_CREDITO\n  ASSINATURA\n  CORTESIA\n  OUTRO\n}\n\nenum StatusAssinatura {\n  ATIVA\n  PAUSADA\n  CANCELADA\n  EXPIRADA\n}\n\nmodel Agendamento {\n  id String @id @default(cuid())\n\n  clienteId      String\n  profissionalId String\n  servicoId      String\n  usoAssinatura  UsoAssinatura?\n\n  inicio DateTime\n  fim    DateTime\n\n  status StatusAgendamento @default(SOLICITADO)\n\n  observacaoCliente   String?\n  observacaoInterna   String?\n  motivoRecusa        String?\n  motivoCancelamento  String?\n  canceladoEm         DateTime?\n  formaPagamento      FormaPagamento?\n  valorPagoCentavos   Int?\n  pagoEm              DateTime?\n  observacaoPagamento String?\n\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  cliente      Usuario      @relation("AgendamentosCliente", fields: [clienteId], references: [id], onDelete: Cascade)\n  profissional Profissional @relation(fields: [profissionalId], references: [id], onDelete: Restrict)\n  servico      Servico      @relation(fields: [servicoId], references: [id], onDelete: Restrict)\n\n  @@index([clienteId])\n  @@index([profissionalId])\n  @@index([servicoId])\n  @@index([status])\n  @@index([formaPagamento])\n  @@index([inicio])\n  @@index([profissionalId, inicio])\n}\n\nmodel BloqueioAgenda {\n  id String @id @default(cuid())\n\n  profissionalId String?\n  inicio         DateTime\n  fim            DateTime\n\n  motivo String?\n  ativo  Boolean @default(true)\n\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  profissional Profissional? @relation(fields: [profissionalId], references: [id], onDelete: Cascade)\n\n  @@index([profissionalId])\n  @@index([inicio])\n  @@index([fim])\n  @@index([ativo])\n  @@index([profissionalId, inicio])\n}\n\nmodel PlanoAssinatura {\n  id             String  @id @default(cuid())\n  nome           String  @unique\n  descricao      String?\n  precoCentavos  Int\n  cortesPorCiclo Int\n  duracaoDias    Int     @default(30)\n  ativo          Boolean @default(true)\n\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  assinaturas AssinaturaCliente[]\n\n  @@index([ativo])\n}\n\nmodel AssinaturaCliente {\n  id String @id @default(cuid())\n\n  clienteId String\n  planoId   String\n\n  status StatusAssinatura @default(ATIVA)\n\n  inicio         DateTime @default(now())\n  vigenciaInicio DateTime\n  vigenciaFim    DateTime\n\n  saldoCortes           Int\n  renovaAutomaticamente Boolean @default(false)\n\n  observacao String?\n\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  cliente Usuario         @relation("AssinaturasCliente", fields: [clienteId], references: [id], onDelete: Cascade)\n  plano   PlanoAssinatura @relation(fields: [planoId], references: [id], onDelete: Restrict)\n\n  usos       UsoAssinatura[]\n  pagamentos PagamentoAssinatura[]\n\n  @@index([clienteId])\n  @@index([planoId])\n  @@index([status])\n  @@index([vigenciaFim])\n}\n\nmodel UsoAssinatura {\n  id String @id @default(cuid())\n\n  assinaturaId  String\n  agendamentoId String @unique\n\n  quantidadeCortes Int @default(1)\n\n  criadoEm DateTime @default(now())\n\n  assinatura  AssinaturaCliente @relation(fields: [assinaturaId], references: [id], onDelete: Cascade)\n  agendamento Agendamento       @relation(fields: [agendamentoId], references: [id], onDelete: Cascade)\n\n  @@index([assinaturaId])\n}\n\nmodel PagamentoAssinatura {\n  id String @id @default(cuid())\n\n  assinaturaId   String\n  formaPagamento FormaPagamento\n  valorCentavos  Int\n  pagoEm         DateTime       @default(now())\n  observacao     String?\n\n  criadoEm DateTime @default(now())\n\n  assinatura AssinaturaCliente @relation(fields: [assinaturaId], references: [id], onDelete: Cascade)\n\n  @@index([assinaturaId])\n  @@index([formaPagamento])\n  @@index([pagoEm])\n}\n',
